import React, { useState, FormEvent } from "react";
import { Link } from 'react-router-dom';

/* =====================================================================
 * ASSETS
 * ===================================================================== */
const LOGO_SRC = "data:image/webp;base64,";
const PHOTO_SRC = "data:image/webp;base64,";

/* =====================================================================
 * CONFIGURATION API — à compléter par le développeur backend
 * =====================================================================
 * Le formulaire envoie { email, password } à LOGIN_API_URL.
 * La réponse attendue du serveur doit être un JSON contenant au
 * minimum un champ "role" indiquant le type de compte détecté :
 *   { "role": "admin" | "etudiant" | "enseignant", "token": "..." }
 * ===================================================================== */

const LOGIN_API_URL: string = ""; // TODO: URL de l'endpoint de connexion, ex: "https://api.iua.ci/auth/login"

const REDIRECT_ADMIN_URL: string = ""; // TODO: URL de l'espace administrateur, ex: "/admin/dashboard"
const REDIRECT_ETUDIANT_URL: string = ""; // TODO: URL de l'espace étudiant, ex: "/etudiant/dashboard"
const REDIRECT_ENSEIGNANT_URL: string = ""; // TODO: URL de l'espace enseignant, ex: "/enseignant/dashboard"

type UserRole = "admin" | "etudiant" | "enseignant";

interface LoginResponse {
  role: UserRole;
  token?: string;
}

export default function ConnexionPage() {
  const [email, setEmail] = useState<string>("");
  const [password, setPassword] = useState<string>("");
  const [remember, setRemember] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string>("");

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError("");

    if (!email.trim() || !password) {
      setError("Veuillez renseigner votre email et votre mot de passe.");
      return;
    }

    if (!LOGIN_API_URL) {
      // Pas encore d'API branchée : on informe le développeur au lieu
      // de planter silencieusement.
      setError("Aucune API de connexion configurée (voir LOGIN_API_URL).");
      return;
    }

    setLoading(true);

    try {
      // ---------------------------------------------------------------
      // APPEL API — vérifie l'email + mot de passe et renvoie le rôle
      // ---------------------------------------------------------------
      const response = await fetch(LOGIN_API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim(), password, remember }),
      });

      if (!response.ok) {
        throw new Error("identifiants_invalides");
      }

      const data: LoginResponse = await response.json();

      // ---------------------------------------------------------------
      // AIGUILLAGE SELON LE RÔLE RENVOYÉ PAR L'API
      // ---------------------------------------------------------------
      switch (data.role) {
        case "admin":
          window.location.href = REDIRECT_ADMIN_URL || "#";
          break;
        case "etudiant":
          window.location.href = REDIRECT_ETUDIANT_URL || "#";
          break;
        case "enseignant":
          window.location.href = REDIRECT_ENSEIGNANT_URL || "#";
          break;
        default:
          setError("Rôle utilisateur inconnu. Contactez l'administration.");
      }
    } catch (err) {
      setError("Email ou mot de passe incorrect. Veuillez réessayer.");
    } finally {
      setLoading(false);
    }
  };

  const handleForgotPassword = (e: React.MouseEvent) => {
    e.preventDefault();
    // TODO: rediriger vers la page "mot de passe oublié" ou ouvrir une modale
    console.log("Lien mot de passe oublié cliqué — à connecter.");
  };

  const handleSocialLogin = (provider: "facebook" | "linkedin" | "google") => (
    e: React.MouseEvent
  ) => {
    e.preventDefault();
    // TODO: brancher le flux OAuth correspondant (provider)
    console.log(`Connexion via ${provider} — à connecter.`);
  };

  return (
    <div className="min-h-screen w-full flex bg-white">
      {/* ==================== LEFT: FORM ==================== */}
      <div className="flex-1 max-w-[560px] flex flex-col justify-center px-8 py-12 md:px-16">
        <div className="mb-12">
          <img src={LOGO_SRC} alt="Logo IUA — Institut Universitaire d'Abidjan" className="h-11 w-auto" />
        </div>

        <h1 className="text-3xl font-bold text-blue-600 mb-3">Connexion</h1>
        <p className="text-sm leading-relaxed text-slate-400 mb-9 max-w-sm">
          Bienvenue sur la fenêtre de connexion. Entrez votre email IUA et votre
          mot de passe pour vous connecter.
        </p>

        {error && (
          <div className="mb-5 text-sm text-red-600 bg-red-50 border border-red-200 rounded-lg px-3 py-2.5">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex flex-col gap-5" noValidate>
          <div>
            <label htmlFor="email" className="block text-sm font-semibold text-slate-800 mb-1.5">
              Email IUA
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autoComplete="username"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="prenom.nom@iua.ci"
              className="w-full px-4 py-3 rounded-lg border-[1.5px] border-slate-200 bg-slate-50 text-sm text-slate-800 placeholder:text-blue-300 focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-100 transition"
            />
          </div>

          <div>
            <label htmlFor="password" className="block text-sm font-semibold text-slate-800 mb-1.5">
              Mot de passe
            </label>
            <input
              id="password"
              name="password"
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••••"
              className="w-full px-4 py-3 rounded-lg border-[1.5px] border-slate-200 bg-slate-50 text-sm text-slate-800 placeholder:text-blue-300 focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-100 transition"
            />
          </div>

          <div className="flex items-center justify-between text-sm -mt-1">
            <label className="flex items-center gap-2 text-slate-400 select-none cursor-pointer">
              <input
                type="checkbox"
                checked={remember}
                onChange={(e) => setRemember(e.target.checked)}
                className="w-3.5 h-3.5 accent-blue-600 cursor-pointer"
              />
              Se souvenir de moi
            </label>
            <a
              href="#"
              onClick={handleForgotPassword}
              className="text-blue-600 font-medium hover:underline"
            >
              Mot de passe oublié ?
            </a>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="mt-2 w-full py-3.5 rounded-lg bg-blue-600 text-white text-sm font-bold tracking-wide hover:bg-blue-700 active:translate-y-px disabled:opacity-60 disabled:cursor-not-allowed transition"
          >
            {loading ? "CONNEXION..." : "CONNEXION"}
          </button>
        </form>

        <div className="flex gap-6 text-sm font-semibold mt-10">
          <a href="#" onClick={handleSocialLogin("facebook")} className="text-blue-600 hover:underline">
            Facebook
          </a>
          <a href="#" onClick={handleSocialLogin("linkedin")} className="text-blue-600 hover:underline">
            LinkedIn
          </a>
          <a href="#" onClick={handleSocialLogin("google")} className="text-blue-600 hover:underline">
            Google
          </a>
        </div>
      </div>

      {/* ==================== RIGHT: VISUAL ==================== */}
      <div
        className="hidden md:block flex-1 bg-[#0a1a3c] bg-cover bg-center"
        style={{ backgroundImage: `url(${PHOTO_SRC})` }}
      />
    </div>
  );
}
